        <div class="lesson-callout lgs-trap">
          <strong>🚨 LGS TUZAĞI — "Laid-back", "Sneaky" ve "Tactful" Farkına Dikkat!</strong>
          <ul>
            <li><span class="hl-yellow">Laid-back</span> (= <em>relaxed, calm, easy-going, carefree</em>): "Rahat, telaşsız, hiçbir şeyi kafaya takmayan" demektir. Cümlede <strong>"He never panics or worries"</strong> şeklinde tanımlanır. Dikkat: Genellikle olumlu veya nötr bir özelliktir; ancak çok dakik ve ciddi bir karakter (<em>serious / punctual</em>) bazen fazla <em>laid-back</em> birisiyle anlaşamayabilir!</li>
            <li><span class="hl-coral">Sneaky</span> (= <em>dishonest, two-faced, secret</em>): "Sinsi, içten pazarlıklı" demektir. Soruda <strong>"does things secretly behind my back"</strong> (arkamdan gizlice iş çevirir) ifadesini gördüğünüz an şıklarda <strong>sneaky</strong> arayın!</li>
            <li><span class="hl-green">Tactful</span> (= <em>considerate, kind, polite</em>): "İnce düşünceli, ağzından çıkan lafa dikkat eden, kimseyi kırmayan" demektir. Soruda <strong>"careful not to hurt or upset others"</strong> diyorsa cevap kesinlikle <strong>tactful</strong>'dur.</li>
          </ul>
        </div>

