            <li><span class="hl-blue"><strong>Greasy / Fatty / Fried food:</strong></span> Yağlı / kızartılmış yiyecekler (<em>French fries, fried chicken</em>). <em>"She is on a diet and prefers healthy/grilled food"</em> diyorsa <em>grilled fish/chicken + salad</em> seçilmelidir.</li>
