              <p style="margin-top:0.35rem; font-size:0.86rem;">✅ <strong>TRUE (DOĞRU):</strong> Kaan (<em>cycling, bowling, sci-fi films</em>) ile Nisa (<em>riding a bike, bowling, space movies</em>) birebir aynı ilgi alanlarını paylaşmaktadır (<em>have a lot in common</em>)!</p>
